# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİRA MAĞARASI\'NDA TEFEKKÜR VE İLK VAHİY (610)</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Neden Hira\'da İnziva (Tahannüs)?</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Mekke\'deki putperestlik ve zulümden uzaklaşma</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Nur Dağı\'ndaki Hira Mağarası\'nda yalnız kalma</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Evrenin yaratılışını derinlemesine düşünme (Tefekkür)</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Hz. İbrahim\'in Hanif (tevhid) din üzere ibadeti</text>\n  <text x="187" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Ruhu ve kalbi ağır vahiy yüküne hazırlandı!</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İlk Vahiy: Alak Suresi 1–5. Ayetler</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Tarih: 610 yılı Ramazan ayı (Kadir Gecesi)</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• Vahiy Meleği: Cebrail (a.s.) • Yaş: 40</text>\n  <text x="380" y="156" font-size="11.5" font-weight="bold" fill="#166534">• İlk Emir: «İkra\'!» (Yaratan Rabbinin adıyla oku!)</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">• Kalemle yazmayı ve bilmediğini öğreten Allah\'tır.</text>\n  <text x="512" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">İslam ilim, okuma ve tefekkür üzerine kurulmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. HATİCE\'NİN TESELLİSİ VE VARAKA BİN NEVFEL\'İN TANIKLIĞI</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hz. Hatice\'nin (r.a.) Sarsılmaz Desteği</text>\n  <text x="50" y="108" font-size="11" fill="#334155">"Allah seni mahcup etmez ve yalnız bırakmaz! Çünkü sen;</text>\n  <text x="55" y="130" font-size="11.5" fill="#1e293b">• Akrabanı gözetirsin (sıla-i rahim yaparsın),</text>\n  <text x="55" y="150" font-size="11.5" fill="#1e293b">• Doğru konuşur, emaneti korursun,</text>\n  <text x="55" y="170" font-size="11.5" fill="#1e293b">• Güçsüzlerin ve yoksulların yükünü taşırsın,</text>\n  <text x="55" y="190" font-size="11.5" fill="#1e293b">• Misafire ikram eder, hak yolunda yardım edersin."</text>\n  <text x="187" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Güzel ahlak, peygamberliğin en sağlam zeminidir!</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Varaka bin Nevfel ve Fetret-i Vahiy</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Hz. Hatice\'nin amcasının oğlu, bilge bir âlimdir.</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• Gelen meleğin Hz. Musa\'ya gelen Nâmûs-ı Ekber</text>\n  <text x="390" y="148" font-size="11" fill="#475569">(Cebrail a.s.) olduğunu müjdelemiştir.</text>\n  <text x="380" y="174" font-size="11.5" fill="#334155">• Fetret-i Vahiy: İlk vahiyden sonra vahyin</text>\n  <text x="390" y="192" font-size="11" fill="#475569">bir süre kesilmesi; Müddessir ve Duhâ ile bitti.</text>\n  <text x="512" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Müddessir 1–5 ile Tebliğ görevi başladı!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE ZAMAN ŞERİDİ VE İLK DÖRT MÜSLÜMAN</text>\n  <rect x="30" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Gençlik Yıllarında Peygamberimiz</text>\n  <text x="45" y="108" font-size="11.5" fill="#334155">• Çobanlık ve amcası Ebu Talip ile ticaret</text>\n  <text x="45" y="130" font-size="11.5" fill="#334155">• Ficâr Savaşlarında barış çabası</text>\n  <text x="45" y="152" font-size="11.5" font-weight="bold" fill="#166534">• Hilfü\'l-Fudûl (Erdemliler Topluluğu - ~590)</text>\n  <text x="45" y="174" font-size="11.5" fill="#334155">• Hz. Hatice ile evlilik (595, 25 yaş)</text>\n  <text x="45" y="196" font-size="11.5" font-weight="bold" fill="#166534">• Kâbe Hakemliği (Hacerü\'l-Esved - 605, 35 yaş)</text>\n  <text x="45" y="218" font-size="11.5" fill="#334155">• Hira\'da Tefekkür ve İlk Vahiy (610, 40 yaş)</text>\n  <rect x="360" y="55" width="310" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">İslam\'a Giren İlk Dört Müslüman</text>\n  <text x="380" y="112" font-size="11.5" fill="#334155">1. Hz. Hatice (r.a.): İlk Müslüman (Eşi)</text>\n  <text x="380" y="138" font-size="11.5" fill="#334155">2. Hz. Ali (r.a.): Çocuklardan ilk (Amcasının oğlu)</text>\n  <text x="380" y="164" font-size="11.5" fill="#334155">3. Hz. Zeyd bin Hârise (r.a.): Azatlılardan ilk</text>\n  <text x="380" y="190" font-size="11.5" fill="#334155">4. Hz. Ebubekir (r.a.): Hür erkeklerden ilk (Dostu)</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Onu en yakından tanıyanlar hiç tereddüt etmedi!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
